1	// Meeting-room booking server: JSON API + static page, data kept in one JSON file.
2	// Node.js built-ins only. Startup order: PORT check -> data file read -> listen.
3	import http from 'node:http';
4	import { readFileSync } from 'node:fs';
5	import { readFile, writeFile } from 'node:fs/promises';
6	import path from 'node:path';
7	import { fileURLToPath } from 'node:url';
8	
9	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
10	const MAX_BODY_BYTES = 10000;
11	const MAX_TITLE_LENGTH = 80;
12	const DEFAULT_PORT = 3000;
13	const MAX_PORT = 65535;
14	const HOST = '127.0.0.1';
15	const JSON_TYPE = 'application/json; charset=utf-8';
16	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
17	const PAGE_FILES = Object.freeze({
18	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
19	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
20	});
21	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
22	const BOOKINGS_PREFIX = '/api/bookings/';
23	
24	class HttpError extends Error {
25	  constructor(status, message) {
26	    super(message);
27	    this.status = status;
28	  }
29	}
30	
31	// ---------- validation helpers ----------
32	
33	function isPlainObject(value) {
34	  return typeof value === 'object' && value !== null && !Array.isArray(value);
35	}
36	
37	function isValidDate(value) {
38	  if (typeof value !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
39	  const year = Number(value.slice(0, 4));
40	  const month = Number(value.slice(5, 7));
41	  const day = Number(value.slice(8, 10));
42	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
43	  const febDays = year % 4 === 0 ? 29 : 28;
44	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
45	  return day <= monthDays[month - 1];
46	}
47	
48	function isValidTime(value) {
49	  if (typeof value !== 'string' || !/^[0-9]{2}:[0-9]{2}$/.test(value)) return false;
50	  return Number(value.slice(0, 2)) <= 23 && Number(value.slice(3, 5)) <= 59;
51	}
52	
53	function ownField(object, key) {
54	  return Object.hasOwn(object, key) ? object[key] : undefined;
55	}
56	
57	function overlaps(a, b) {
58	  return a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
59	}
60	
61	// Rules 4-9: returns a new booking draft (without id) or throws HttpError 400.
62	function validateBookingFields(body) {
63	  const room = ownField(body, 'room');
64	  if (typeof room !== 'string' || !ROOMS.includes(room)) {
65	    throw new HttpError(400, 'room must be one of Aurora, Borealis, Cosmos');
66	  }
67	  const rawTitle = ownField(body, 'title');
68	  const title = typeof rawTitle === 'string' ? rawTitle.trim() : '';
69	  if (title.length < 1 || title.length > MAX_TITLE_LENGTH) {
70	    throw new HttpError(400, 'title must be 1 to 80 characters');
71	  }
72	  const date = ownField(body, 'date');
73	  if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
74	  const start = ownField(body, 'start');
75	  if (!isValidTime(start)) throw new HttpError(400, 'start must be HH:MM');
76	  const end = ownField(body, 'end');
77	  if (!isValidTime(end)) throw new HttpError(400, 'end must be HH:MM');
78	  if (end <= start) throw new HttpError(400, 'end must be after start');
79	  return { room, title, date, start, end };
80	}
81	
82	function compareBookings(a, b) {
83	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
84	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
85	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
86	}
87	
88	// ---------- data file ----------
89	
90	function isValidStoredBooking(entry, nextId) {
91	  if (!isPlainObject(entry)) return false;
92	  const keys = Object.keys(entry);
93	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
94	  const { id, room, title, date, start, end } = entry;
95	  return Number.isSafeInteger(id) && id >= 1 && id < nextId
96	    && typeof room === 'string' && ROOMS.includes(room)
97	    && typeof title === 'string' && title === title.trim()
98	    && title.length >= 1 && title.length <= MAX_TITLE_LENGTH
99	    && isValidDate(date) && isValidTime(start) && isValidTime(end) && start < end;
100	}
101	
102	// Returns a fresh state, or null when the data is not in this server's layout.
103	function parseState(text) {
104	  let data;
105	  try {
106	    data = JSON.parse(text);
107	  } catch {
108	    return null;
109	  }
110	  if (!isPlainObject(data)) return null;
111	  const keys = Object.keys(data);
112	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return null;
113	  const { nextId, bookings } = data;
114	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return null;
115	  if (!bookings.every((b) => isValidStoredBooking(b, nextId))) return null;
116	  if (new Set(bookings.map((b) => b.id)).size !== bookings.length) return null;
117	  const clash = bookings.some((a, i) => bookings.some((b, j) => i < j && overlaps(a, b)));
118	  if (clash) return null;
119	  return Object.freeze({ nextId, bookings: Object.freeze(bookings.map((b) => Object.freeze({ ...b }))) });
120	}
121	
122	function loadState(filePath) {
123	  let buffer;
124	  try {
125	    buffer = readFileSync(filePath);
126	  } catch (error) {
127	    if (error && error.code === 'ENOENT') return Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
128	    return null;
129	  }
130	  return parseState(buffer.toString('utf8'));
131	}
132	
133	function saveState(filePath, state) {
134	  const payload = { nextId: state.nextId, bookings: state.bookings };
135	  return writeFile(filePath, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
136	}
137	
138	// ---------- request / reply helpers ----------
139	
140	// Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts all of them.
141	function readBody(req) {
142	  return new Promise((resolve, reject) => {
143	    const chunks = [];
144	    let kept = 0;
145	    let total = 0;
146	    req.on('data', (chunk) => {
147	      total += chunk.length;
148	      if (kept <= MAX_BODY_BYTES) {
149	        chunks.push(chunk);
150	        kept += chunk.length;
151	      }
152	    });
153	    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
154	    req.on('error', reject);
155	  });
156	}
157	
158	function sendJson(res, status, value) {
159	  const body = Buffer.from(JSON.stringify(value), 'utf8');
160	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': body.length });
161	  res.end(body);
162	}
163	
164	function sendError(res, status, message) {
165	  sendJson(res, status, { error: message });
166	}
167	
168	function mediaTypeIsJson(header) {
169	  if (typeof header !== 'string') return false;
170	  const mediaType = header.split(';', 1)[0].replace(/^[ \t]+|[ \t]+$/g, '');
171	  return mediaType.replace(/[A-Z]/g, (c) => c.toLowerCase()) === 'application/json';
172	}
173	
174	function parseJsonObject(buffer) {
175	  try {
176	    const value = JSON.parse(buffer.toString('utf8'));
177	    return isPlainObject(value) ? value : null;
178	  } catch {
179	    return null;
180	  }
181	}
182	
183	// ---------- app ----------
184	
185	function createApp(dataPath, initialState) {
186	  let state = initialState;
187	  let lock = Promise.resolve();
188	
189	  // Runs mutations one at a time so concurrent requests behave as if sequential.
190	  function serialized(task) {
191	    const run = lock.then(task);
192	    lock = run.then(() => undefined, () => undefined);
193	    return run;
194	  }
195	
196	  async function commit(nextState) {
197	    await saveState(dataPath, nextState);
198	    state = nextState;
199	  }
200	
201	  function listBookings(res, query) {
202	    const params = new URLSearchParams(query);
203	    let bookings = state.bookings;
204	    if (params.has('date')) {
205	      const date = params.get('date');
206	      if (!isValidDate(date)) throw new HttpError(400, 'date must be a valid YYYY-MM-DD date');
207	      bookings = bookings.filter((b) => b.date === date);
208	    }
209	    sendJson(res, 200, { bookings: [...bookings].sort(compareBookings) });
210	  }
211	
212	  function createBooking(req, res, body) {
213	    if (!mediaTypeIsJson(req.headers['content-type'])) {
214	      throw new HttpError(415, 'content type must be application/json');
215	    }
216	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, 'body too large');
217	    const parsed = parseJsonObject(body.buffer);
218	    if (parsed === null) throw new HttpError(400, 'body must be a JSON object');
219	    const draft = validateBookingFields(parsed);
220	    return serialized(async () => {
221	      const clashes = state.bookings.filter((b) => overlaps(b, draft)).sort(compareBookings);
222	      if (clashes.length > 0) {
223	        throw new HttpError(409, `room is already booked from ${clashes[0].start} to ${clashes[0].end}`);
224	      }
225	      const booking = Object.freeze({ id: state.nextId, ...draft });
226	      await commit(Object.freeze({
227	        nextId: state.nextId + 1,
228	        bookings: Object.freeze([...state.bookings, booking]),
229	      }));
230	      sendJson(res, 201, booking);
231	    });
232	  }
233	
234	  function deleteBooking(res, idText) {
235	    return serialized(async () => {
236	      const valid = /^[1-9][0-9]*$/.test(idText);
237	      const target = valid ? state.bookings.find((b) => String(b.id) === idText) : undefined;
238	      if (!target) throw new HttpError(404, 'booking not found');
239	      await commit(Object.freeze({
240	        nextId: state.nextId,
241	        bookings: Object.freeze(state.bookings.filter((b) => b !== target)),
242	      }));
243	      res.writeHead(204);
244	      res.end();
245	    });
246	  }
247	
248	  async function servePage(res, page) {
249	    const content = await readFile(path.join(PUBLIC_DIR, page.file));
250	    res.writeHead(200, { 'Content-Type': page.type, 'Content-Length': content.length });
251	    res.end(content);
252	  }
253	
254	  function methodNotAllowed() {
255	    throw new HttpError(405, 'method not allowed');
256	  }
257	
258	  async function route(req, res, body) {
259	    const target = req.url;
260	    const cut = target.indexOf('?');
261	    const pathname = cut === -1 ? target : target.slice(0, cut);
262	    const query = cut === -1 ? '' : target.slice(cut + 1);
263	    const { method } = req;
264	
265	    if (pathname === '/api/rooms') {
266	      if (method !== 'GET') methodNotAllowed();
267	      return sendJson(res, 200, { rooms: [...ROOMS] });
268	    }
269	    if (pathname === '/api/bookings') {
270	      if (method === 'GET') return listBookings(res, query);
271	      if (method === 'POST') return createBooking(req, res, body);
272	      return methodNotAllowed();
273	    }
274	    if (pathname.startsWith(BOOKINGS_PREFIX)) {
275	      const idText = pathname.slice(BOOKINGS_PREFIX.length);
276	      if (idText === '' || idText.includes('/')) throw new HttpError(404, 'not found');
277	      if (method !== 'DELETE') methodNotAllowed();
278	      return deleteBooking(res, idText);
279	    }
280	    if (Object.hasOwn(PAGE_FILES, pathname)) {
281	      if (method !== 'GET') methodNotAllowed();
282	      return servePage(res, PAGE_FILES[pathname]);
283	    }
284	    throw new HttpError(404, 'not found');
285	  }
286	
287	  return async function handle(req, res) {
288	    let body;
289	    try {
290	      body = await readBody(req);
291	    } catch {
292	      // The client went away mid-body; there is nobody left to reply to.
293	      req.destroy();
294	      return;
295	    }
296	    try {
297	      await route(req, res, body);
298	    } catch (error) {
299	      if (res.headersSent) {
300	        res.destroy();
301	        return;
302	      }
303	      if (error instanceof HttpError) sendError(res, error.status, error.message);
304	      else sendError(res, 500, 'internal error');
305	    }
306	  };
307	}
308	
309	// ---------- startup ----------
310	
311	function fail(line) {
312	  process.stderr.write(`${line}\n`);
313	  process.exit(1);
314	}
315	
316	function parsePort(raw) {
317	  if (raw === undefined || raw === '') return DEFAULT_PORT;
318	  if (!/^[0-9]+$/.test(raw)) return null;
319	  const port = Number(raw);
320	  return port <= MAX_PORT ? port : null;
321	}
322	
323	function main() {
324	  const port = parsePort(process.env.PORT);
325	  if (port === null) fail(`invalid PORT ${process.env.PORT}`);
326	
327	  const dataName = process.env.DATA_FILE ? process.env.DATA_FILE : 'bookings.json';
328	  const dataPath = path.resolve(process.cwd(), dataName);
329	  const state = loadState(dataPath);
330	  if (state === null) fail(`cannot read data file ${dataName}`);
331	
332	  const server = http.createServer(createApp(dataPath, state));
333	  server.on('error', (error) => fail(`cannot listen on port ${port}: ${error.code || 'error'}`));
334	  server.listen(port, HOST, () => {
335	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
336	  });
337	}
338	
339	main();
